class ChatEventBuilder(EventBuilder):
    """Builder for chat modality events."""

    def __init__(self):
        super().__init__("chat")
        self._data = {
            "operation": "send_message",
            "role": "user",
            "content": "",
            "conversation_id": "default",
        }

class SMSEventBuilder(EventBuilder):
    """Builder for SMS modality events."""

    def __init__(self):
        super().__init__("sms")
        self._data = {
            "action": "receive_message",
            "message_data": {
                "to_numbers": [],
                "message_type": "sms",
            },
        }

    def receive(self) -> Self:
        """Set action to receive (incoming SMS)."""
        self._data["action"] = "receive_message"
        return self

    def send(self) -> Self:
        """Set action to send (outgoing SMS)."""
        self._data["action"] = "send_message"
        return self

class CalendarEventBuilder(EventBuilder):
    """Builder for calendar modality events."""

    def __init__(self):
        super().__init__("calendar")
        self._data = {
            "operation": "create",
        }

    def create(self) -> Self:
        """Set action to create a calendar event."""
        self._data["operation"] = "create"
        return self

    def update(self, event_id: str) -> Self:
        """Set action to update an existing event."""
        self._data["operation"] = "update"
        self._data["event_id"] = event_id
        return self

    def delete(self, event_id: str) -> Self:
        """Set action to delete an event."""
        self._data["operation"] = "delete"
        self._data["event_id"] = event_id
        return self

    def title(self, title: str) -> Self:
        """Set the event title."""
        self._data["title"] = title
        return self

    def description(self, description: str) -> Self:
        """Set the event description."""
        self._data["description"] = description
        return self

    def start(self, time: datetime | str) -> Self:
        """Set the event start time."""
        if isinstance(time, datetime):
            time = time.isoformat()
        self._data["start"] = time
        return self

    def end(self, time: datetime | str) -> Self:
        """Set the event end time."""
        if isinstance(time, datetime):
            time = time.isoformat()
        self._data["end"] = time
        return self

    def location(self, location: str) -> Self:
        """Set the event location."""
        self._data["location"] = location
        return self

    def attendees(self, *emails: str) -> Self:
        """Set the event attendees as simple email list."""
        # Convert to list of Attendee-like dicts
        self._data["attendees"] = [
            {"email": email} for email in emails
        ]
        return self

    def reminder(self, minutes_before: int, method: str = "notification") -> Self:
        """Add a reminder to the event."""
        if "reminders" not in self._data:
            self._data["reminders"] = []
        self._data["reminders"].append({
            "minutes_before": minutes_before,
            "type": method,
        })
        return self

    def on_calendar(self, calendar_id: str) -> Self:
        """Set which calendar to add the event to."""
        self._data["calendar_id"] = calendar_id
        return self

@staticmethod
def location_is(name: str) -> AssertionFunc:
    """Assert the current location name."""
    def check(state: dict[str, Any]) -> None:
        data = state.get("state", state)
        current = data.get("current_location", data.get("current", {}))
        actual = current.get("named_location", current.get("location_name", current.get("name", "")))
        assert actual == name, f"Expected location '{name}', got '{actual}'"
    return check

@staticmethod
def weather_conditions(expected: str) -> AssertionFunc:
    """Assert the current weather conditions."""
    def check(state: dict[str, Any]) -> None:
        data = state.get("state", state)
        # Weather uses OpenWeather format stored in locations dict
        locations = data.get("locations", {})
        found = False
        for loc_data in locations.values():
            # Try getting conditions from OpenWeather format
            current_report = loc_data.get("current_report", {})
            current = current_report.get("current", {})
            weather = current.get("weather", [])
            if weather:
                conditions = weather[0].get("main", "")
                if conditions == expected:
                    found = True
                    break
            # Also try legacy format
            if loc_data.get("conditions") == expected:
                found = True
                break
        # Try simple reports format too
        reports = data.get("reports", {})
        if isinstance(reports, dict):
            for r in reports.values():
                if isinstance(r, dict) and r.get("conditions") == expected:
                    found = True
                    break
        assert found, f"Weather conditions '{expected}' not found"
    return check

@staticmethod
def weather_temperature_range(min_temp: float, max_temp: float) -> AssertionFunc:
    """Assert temperature is within the given range (in Celsius)."""
    def check(state: dict[str, Any]) -> None:
        data = state.get("state", state)
        temps = []
        # Weather uses OpenWeather format stored in locations dict
        locations = data.get("locations", {})
        for loc_data in locations.values():
            current_report = loc_data.get("current_report", {})
            current = current_report.get("current", {})
            temp_k = current.get("temp")
            if temp_k is not None:
                # Convert from Kelvin to Celsius
                temp_c = temp_k - 273.15
                temps.append(temp_c)
        # Also try legacy format
        reports = data.get("reports", {})
        if isinstance(reports, dict):
            for r in reports.values():
                if isinstance(r, dict):
                    t = r.get("temperature")
                    if t is not None:
                        temps.append(t)
        if not temps:
            raise AssertionError("No temperature data found")
        for temp in temps:
            assert min_temp <= temp <= max_temp, f"Temperature {temp}°C not in range [{min_temp}, {max_temp}]"
    return check

